378	/// Forbidden Alchemy reveals top 4, player picks 1 for hand, rest go to graveyard.
379	#[test]
380	fn forbidden_alchemy_draws_and_mills() {
381	    use mtg_engine::actions::ResolvedChoice;
382	
383	    let reg = registry();
384	    let mut state = game_at_step(Step::PrecombatMain, P0);
385	
386	    // Stock library with 5 cards.
